public void message(final Contact contact, final Message message) {
  try {
    final String target = contact.getAddress();
    this.irc.message(target, message.getContent(), new Callback<String>() {
      @Override
      public void onSuccess(String msg) {
        IrcStack.this.provider.getBasicInstantMessaging().fireMessageDelivered(message, contact);
        LOGGER.trace("Successfully delivered message.");
      }
      @Override
      public void onFailure(Exception e) {
        IrcStack.this.provider.getBasicInstantMessaging().fireMessageDeliveryFailed(message, contact, MessageDeliveryFailedEvent.UNKNOWN_ERROR);
        LOGGER.trace("Failed to deliver message.", e);
      }
    });
  } catch (RuntimeException e) {
    LOGGER.error("Unexpected runtime exception in message sending.", e);
    throw e;
  }
}
